import{c as a,Q as r,j as s,m as t}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"Claude Opus 4.1 System Card (Addendum)","description":"","frontmatter":{"url":"https://www.anthropic.com/claude-opus-4-1-system-card","title":"Claude Opus 4.1 System Card (Addendum)","archived_date":"2026-06-24T00:00:00.000Z","authors":["Anthropic"],"domains":["system-card"],"published_date":"2025-08-01T00:00:00.000Z","source_url":"https://www.anthropic.com/claude-opus-4-1-system-card","web_only":true},"headers":[],"relativePath":"research/papers/2025-08-01-claude-opus-4-1-system-card.md","filePath":"research/papers/2025-08-01-claude-opus-4-1-system-card.md","lastUpdated":1785909234000}'),o={name:"research/papers/2025-08-01-claude-opus-4-1-system-card.md"};function d(l,e,n,c,i,u){return r(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="claude-opus-4-1-system-card-addendum" tabindex="-1">Claude Opus 4.1 System Card (Addendum) <a class="header-anchor" href="#claude-opus-4-1-system-card-addendum" aria-label="Permalink to &quot;Claude Opus 4.1 System Card (Addendum)&quot;">​</a></h1><p><strong>Source</strong>: Anthropic 官方 system card addendum（web-only，無 arXiv PDF）— <a href="https://www.anthropic.com/claude-opus-4-1-system-card" target="_blank" rel="noreferrer">https://www.anthropic.com/claude-opus-4-1-system-card</a> （原始 URL 307 重導向至官方 PDF <code>www-cdn.anthropic.com/.../Claude%204.1%20System%20Card.pdf</code>，內容相同。） <strong>Published</strong>: August 1, 2025（公開報導多記為 2025-08-05 發布）</p><blockquote><p>依官方公開資訊整理；數字以可交叉驗證者為主，不確定處保守描述。</p></blockquote><hr><h2 id="摘要-依官網內容整理" tabindex="-1">摘要（依官網內容整理） <a class="header-anchor" href="#摘要-依官網內容整理" aria-label="Permalink to &quot;摘要（依官網內容整理）&quot;">​</a></h2><p>Opus 4.1 為 Opus 4 的增量升級（addendum 形式 system card），主打 coding 重構（refactoring）、深度研究與 agentic search 的細節追蹤，並提升安全/拒答可靠度。安全檔位延續 Opus 4。</p><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="模型與定位" tabindex="-1">模型與定位 <a class="header-anchor" href="#模型與定位" aria-label="Permalink to &quot;模型與定位&quot;">​</a></h3><ul><li><strong>Claude Opus 4.1</strong>：Opus 4 的小幅迭代旗艦，非全新世代。</li><li>重點：refactoring、in-depth research、detail tracking、agentic search。</li></ul><h3 id="關鍵能力-安全評估數字-依官方公開資訊整理" tabindex="-1">關鍵能力 / 安全評估數字（依官方公開資訊整理） <a class="header-anchor" href="#關鍵能力-安全評估數字-依官方公開資訊整理" aria-label="Permalink to &quot;關鍵能力 / 安全評估數字（依官方公開資訊整理）&quot;">​</a></h3><ul><li><strong>SWE-bench Verified</strong>：<strong>74.5%</strong>（由 Opus 4 的 72.5% 提升，+2pp）。</li><li><strong>Harmless response rate（無害回應率）</strong>：<strong>98.76%</strong>（由 Opus 4 的 97.27% 提升）。</li><li><strong>AI Safety Level</strong>：延續 <strong>ASL-3</strong>（與 Opus 4 同檔）。</li></ul><h3 id="值得注意章節" tabindex="-1">值得注意章節 <a class="header-anchor" href="#值得注意章節" aria-label="Permalink to &quot;值得注意章節&quot;">​</a></h3><ul><li>以 addendum 形式發布——僅記錄相對 Opus 4 的差異，未重做完整評測套件。</li><li>安全側主要為拒答可靠度的漸進改善，未公開新增重大紅線行為。</li></ul><hr><h2 id="workspace-關聯-評估" tabindex="-1">Workspace 關聯（評估） <a class="header-anchor" href="#workspace-關聯-評估" aria-label="Permalink to &quot;Workspace 關聯（評估）&quot;">​</a></h2><ul><li><strong>小數點升級（4 → 4.1）的遷移紀律</strong>：對應 context-management.md「mid-session 禁切模型」——升級於新 session 進行；prompt scaffolding 多半可沿用（與後續 4.7 那種破壞性 tokenizer/API 變更不同）。</li><li><strong>harmless rate ↑ ↔ TEST 階段</strong>：拒答可靠度提升不等於對齊已解，core.md「測試通過 ≠ 四軸通過」仍成立。</li><li><strong><code>pilot</code>（tier=ceiling，原 <code>opus-pilot</code>） 基線</strong>：Opus 4.1 是 Opus 系列早期 ceiling 參照點之一。</li></ul>',17)])])}const m=a(o,[["render",d]]);export{h as __pageData,m as default};
